{
  "schema": "upstate.application-component-fragment/v1",
  "id": "geographic-study-receiving",
  "source_reference": "ES-20261012-ASTRA-S1 / ES26 selected Geographic scientific report to original editable case. Preserve captured Study lineage and the existing Geographic workbench; no reverse study-transfer dependency on its Geographic consumer.",
  "components": {
    "geographic-study-receiving": {
      "title": "Receive selected Geographic studies and continue the original editable case",
      "paths": [
        "integration/component_fragments/geographic-study-receiving.json",
        "model/geographic_study_transfer.py",
        "model/geographic_study_receiving.py",
        "operator/geographic_receiving.py",
        "operator/web/geographic_received_studies.mjs",
        "model/GEOGRAPHIC_STUDY_RECEIVING.md",
        "source_tools/geographic_headwaters_handover.py",
        "source_tools/simulated_headwaters_handover.py",
        "CURRENT_OWNER_DIRECTION.md"
      ],
      "requires": [
        "geographic-operator",
        "study-transfer"
      ]
    }
  },
  "extend_components": {
    "study-transfer": {
      "paths": [
        "model/geographic_study_transfer.py",
        "model/geographic_study_receiving.py",
        "operator/geographic_receiving.py",
        "operator/web/geographic_received_studies.mjs",
        "source_tools/geographic_headwaters_handover.py",
        "source_tools/simulated_headwaters_handover.py",
        "model/GEOGRAPHIC_STUDY_RECEIVING.md"
      ]
    }
  },
  "required_components": [
    "geographic-study-receiving"
  ]
}

{
  "schema": "upstate.operator-extension/v1",
  "id": "study-transfer",
  "title": "Study transfer",
  "version": "1",
  "order": 88,
  "assets": [
    "extensions/study_transfer.mjs",
    "extensions/study_transfer.css",
    "received_studies.mjs",
    "geographic_received_studies.mjs",
    "gauge_received_studies.mjs",
    "ensemble_received_studies.mjs",
    "observed_landcover_received.mjs",
    "observed_landcover_received.css",
    "study_report_navigation.mjs",
    "economic_received_comparisons.mjs",
    "received_published_reviews.mjs",
    "received_published_reviews.css",
    "assessment_received_studies.mjs",
    "parameter_received_studies.mjs"
  ],
  "requires_actions": [
    "workspace.restore"
